using System.Diagnostics.CodeAnalysis;
namespace Foundgine.Providers.Orm;

/// <summary>
/// Write-side seam between the shared mutation executor and a concrete ORM. Reads for update/delete use
/// tracked queries so the ORM's own unit of work performs the change; keys generated by the database are
/// visible on the entity after <see cref="SaveChanges"/>.
/// </summary>
public interface IOrmMutationSource
{
    /// <summary>
    /// Starts a transaction or joins the ambient one. A joined transaction is never committed or disposed
    /// by Foundgine, but Rollback must abort the ambient transaction on batch failure so a partially flushed
    /// batch cannot later be committed accidentally by its owner.
    /// </summary>
    IOrmTransaction BeginTransaction();

    IQueryable<TEntity> TrackedQuery<[DynamicallyAccessedMembers(OrmEntityMembers.Required)] TEntity>() where TEntity : class;
    void Add<[DynamicallyAccessedMembers(OrmEntityMembers.Required)] TEntity>(TEntity entity) where TEntity : class;
    void Remove<[DynamicallyAccessedMembers(OrmEntityMembers.Required)] TEntity>(TEntity entity) where TEntity : class;

    /// <summary>Flushes pending changes inside the current transaction.</summary>
    int SaveChanges();
}

/// <summary>Disposing without <see cref="Commit"/> rolls back.</summary>
public interface IOrmTransaction : IDisposable
{
    void Commit();
    void Rollback();
}
